SELECT * FROM financial_cloud_metric_value
WHERE (data_time = #{query.dataTime} OR (data_time = #{query.firstMonth} AND frequency = 'YEAR'))

AND data_time = #{query.dataTime}

    and metric_name like concat('%',#{query.metricName},'%')


    and metric_first_type = #{query.metricFirstType}


    and metric_second_type = #{query.metricSecondType}


    and frequency = #{query.frequency}

ORDER BY frequency, sort_no

